import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`creator-profile-audit`,heroTitle:`Audit your creator profile in minutes`,heroSubtitle:`Perplexity Computer analyzes your formats, hooks, and engagement patterns, then builds a playbook of what to repeat, improve, or stop — automatically.`,inputUrlCta:`Audit my profile`,inputUrlPlaceholder:`your profile URL`,inputUrlPrefill:`Go to {url} and perform a comprehensive creator profile audit. 1) Analyze the last 30-50 posts to identify content formats used (carousels, reels, static posts, threads, long-form, short-form) and their relative engagement. 2) Break down hook styles — first lines, thumbnails, opening seconds — and score which hooks drive the most engagement. 3) Map the core topics and content pillars, noting which topics consistently outperform and which underperform. 4) Evaluate posting cadence — frequency, timing, day-of-week patterns — and flag inconsistencies or missed windows. 5) Analyze engagement patterns — likes, comments, shares, saves — and identify which content types drive each. 6) Deliver a prioritized action plan with three sections: what to repeat (top-performing formats, hooks, and topics), what to improve (underperforming content with specific fixes), and what to stop doing (low-ROI formats or topics dragging down performance). Include specific examples from their own posts for every recommendation.`,heroOverlaySteps:[`Scanning your recent posts for formats, hooks, and topics`,`Mapping engagement patterns across content types`,`Scoring posting cadence and identifying performance gaps`,`Repeat, improve, and stop recommendations — ready to execute`],generatingSteps:[`Visiting {url} to analyze your content formats, hooks, and engagement data`,`Designing an agent to score every post by format, topic, and hook performance`,`Configuring cadence analysis and engagement pattern detection across your content history`,`Setting up your prioritized action plan with repeat, improve, and stop recommendations`],featureSectionTitle:`From profile URL to content playbook`,featureCardTitles:[`Connects to your creator stack`,`Outputs you can act on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Notion, Google Drive, Canva, Slack — Computer pipes your audit insights and content plans straight into the tools you already use.`,`Format performance scorecards. Hook effectiveness rankings. Topic-by-topic engagement breakdowns. A prioritized playbook telling you exactly what to repeat, improve, and stop.`],capabilitySectionTitle:`Your content strategist, on autopilot`,capabilitySectionSubtitle:`Paste your profile, step away, come back to a complete content audit.`,capabilityCards:[{title:`Format Analysis`,description:`Computer can break down every content format you use — reels, carousels, static posts, threads — and rank them by engagement performance.`},{title:`Hook Scoring`,description:`Computer can analyze your opening lines, thumbnails, and first seconds — and identify which hook styles consistently drive clicks and engagement.`},{title:`Topic Mapping`,description:`Computer can map your content pillars and score each topic by reach, saves, and comments — surfacing what your audience actually wants more of.`},{title:`Connect Your Tools`,description:`Computer can push audit results and content plans into Google Sheets, Notion, Trello, and Slack — build workflows across your entire creator stack.`},{title:`Track Progress`,description:`Computer can remember your past audits, engagement benchmarks, and content experiments — so every new audit measures real improvement over time.`},{title:`Monitor & Alert`,description:`Computer can re-audit your profile weekly and flag when engagement drops, a format stops performing, or a new content pattern starts working.`}]});export{t as default};
